using System;using System.Collections.Generic;class CloneSlice{public readonly Dictionary<string,RebirthStationDiscoveryAdmissionBinding> StationDiscoveryAdmissions = new Dictionary<string,RebirthStationDiscoveryAdmissionBinding>(StringComparer.Ordinal);public CloneSlice Clone(){var copy=new CloneSlice();foreach(var pair in StationDiscoveryAdmissions) copy.StationDiscoveryAdmissions.Add(pair.Key,pair.Value.Clone());return copy;}}